/* Auditoria de Compras — módulo atualizado (origem: sistema-de-auditoria).
   O portal baixa o sistema do Supabase (portal-file/PORTAL_ESPOSENDE_V4_AUTH.html); este patch troca
   só o módulo "desc" (MENC.desc) antes de ele ser aberto. Novidades:
   - Painel corrigido: gráfico mensal Gasto × Economia sem distorção (clique no mês abre os pedidos),
     rankings com valor fora da barra + economia/% de desconto, rosca nítida com % por área,
     comparativo por ano legível, cliques de filtro/detalhe que estavam quebrados voltam a funcionar.
   - Botão "Relatório Diretoria": economia mês a mês do período selecionado, fornecedor × mês,
     destaques automáticos, comparação com o ano anterior, ROI opcional, Imprimir/PDF e Excel.
   Para voltar ao módulo anterior: remova a linha do compras-modulo-patch.js no index.html. */
(function(){
  var B64="";
  function aplicar(){
    if(typeof MENC==='undefined')return false;
    MENC.desc=B64;
    try{if(typeof BLOBS!=='undefined'&&BLOBS.desc){URL.revokeObjectURL(BLOBS.desc);delete BLOBS.desc;}}catch(e){}
    window.__COMPRAS_MODULO_VERSAO='20261105-diretoria';
    return true;
  }
  if(!aplicar())document.addEventListener('DOMContentLoaded',aplicar);
})();
